"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[1251],{92064:e=>{e.exports=JSON.parse('{"functions":[{"name":"SetJumpPaused","desc":"Suspends event scheduling for the duration of a jump. Pausing force-finishes\\nany Active channel through its existing `activeFinish`, the same path the\\nMaxActiveDistance watchdog and `Reset` use. Because `PirateAttackEvent`\\nregisters its wave as `ctx.janitor:Add(wave, \\"Destroy\\")`, that despawns any\\nsurviving attackers \u2014 jumping mid-raid leaves them behind, which is what makes\\n\\"players are safe inside the wormhole\\" actually true.\\n\\nThe odometer is suspended, not reset, so encounter pacing resumes unchanged.\\n\\n`VoidSwarmEvent` also registers its wave as `ctx.janitor:Add(wave, \\"Destroy\\")`,\\nso a jump despawns a live void swarm the same way.","params":[{"name":"paused","desc":"","lua_type":"boolean"}],"returns":[],"function_type":"static","source":{"line":298,"path":"src/ServerStorage/SharedModules/EventOrchestrator.luau"}}],"properties":[],"types":[],"name":"EventOrchestrator","desc":"Server-authoritative scheduler that decides when in-game events fire. Drives\\na virtual odometer (distance the train has traveled, accumulated only while\\nrunning) and one independent state machine per channel. Each channel rolls a\\nweighted table at a configurable distance cadence; the roll may come up empty\\n(a `Nothing` entry) with a pity guard that forces a real event after enough\\nempty rolls. Events plug in as handler modules implementing EventHandler.\\n\\nAll tuning lives in EventConfig. The orchestrator never touches networking \u2014\\neach handler owns its own client communication.","realm":["Server"],"source":{"line":16,"path":"src/ServerStorage/SharedModules/EventOrchestrator.luau"}}')}}]);